# Let me first understand the current task by loading grids from the session
import os, re, json

class GridLoader:
    def load(self):
        d = os.path.normpath(os.environ.get('RLM_SESSION_DIR', ''))
        if not d:
            return {}
        session_file = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
        try:
            t = open(session_file).read().replace('\\n', '\n')
            # Find all grids in the format shown
            patterns = []

            # Find "Demo pair n input/output" or "Test input" patterns
            matches = re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t)
            grids = {}
            for m in matches:
                k, h, w = m.group(1), int(m.group(2)), int(m.group(3))
                start = m.end()
                # Try to extract the grid
                remaining = t[start:start + h * w + 2]  # rough bound
                # Find where next section starts
                next_match = re.search(r'\n(Demo pair|\nTest input)', remaining)
                if next_match:
                    chunk = remaining[:next_match.start()]
                else:
                    chunk = remaining[:min(len(remaining), h*w+2)]

                # Parse as grid
                rows = [line.strip().split() for line in chunk.split('\n') if line.strip() and 'Demo' not in line and 'Test' not in line]
                if rows and len(rows) > 0 and all(re.match(r'^\d+$', cell) for row in rows for cell in row if cell != ''):
                    grid = [[int(c) for c in row if c != ''] for row in rows]
                    if 0 < len(grid) <= 30 and 0 < len(grid[0]) <= 30:
                        if k not in grids and len(grid) == h and all(len(r) == w for r in grid):
                            grids[k] = grid
            return grids
        except:
            return {}

loader = GridLoader()
grids = loader.load()
print("Loaded grids:", list(grids.keys()))
for k, v in grids.items():
    print(f"{k}: {v[0]}x{v[1]}")
    print(v[:3] if len(v[0]) > 3 else v)
    print()

